<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/purchase_step14.php';if(empty($_SESSION['pret_csrf']))$_SESSION['pret_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['pret_csrf'];$error=null;$success=null;$available=[];$returns=[];
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$id=purchase_step14_return_received($pdo,(int)$_POST['receipt_item_id'],(float)$_POST['quantity'],(string)$_POST['return_date'],(float)($_POST['credit_amount']??0),(string)($_POST['reason']??''));$success='Purchase Return #'.$id.' posted and supplier credit updated.';}$stmt=$pdo->prepare("SELECT ri.id receipt_item_id,ri.quantity_received,ri.returned_quantity,(ri.quantity_received-ri.returned_quantity) returnable,ri.unit_cost,ri.batch_code,ri.inventory_batch_id,p.product_name,p.sku,r.receipt_number,r.receipt_date,b.invoice_number,s.supplier_name,ib.current_quantity batch_stock FROM purchase_receipt_items ri JOIN purchase_receipts r ON r.id=ri.purchase_receipt_id AND r.organization_id=ri.organization_id JOIN purchase_bills b ON b.id=r.purchase_bill_id AND b.organization_id=r.organization_id JOIN purchase_suppliers s ON s.id=r.supplier_id AND s.organization_id=r.organization_id JOIN products p ON p.id=ri.product_id AND p.organization_id=ri.organization_id JOIN inventory_batches ib ON ib.id=ri.inventory_batch_id AND ib.organization_id=ri.organization_id WHERE ri.organization_id=? AND ri.returned_quantity<ri.quantity_received-0.0005 ORDER BY r.receipt_date DESC,ri.id DESC");$stmt->execute([$orgId]);$available=$stmt->fetchAll();$returns=purchase_step14_return_rows($pdo,$orgId);}catch(Throwable $e){$error=$e->getMessage();}
function pret_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function pret_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Returns - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Purchase Returns</small></span></a><div class="os-top-actions"><a class="os-btn" href="purchase_receipts.php">Receipts</a><a class="os-btn" href="supplier_payments.php">Payables</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a href="purchase_orders.php"><i class="dot"></i>Purchase Orders</a><a href="purchase_bills.php"><i class="dot"></i>Bills / Invoices</a><a href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a class="active" href="purchase_returns.php"><i class="dot"></i>Returns</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 14F • PURCHASE RETURNS</div><h1>Return stock to the supplier without deleting the original receipt.</h1><p>The exact receipt item and inventory batch remain linked. The actual supplier Credit Note amount reduces payable while the original Bill and Goods Receipt stay preserved.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PURCHASE RETURNS LIVE':'Review required' ?></span><span class="os-chip"><?= count($available) ?> returnable receipt lines</span><span class="os-chip"><?= count($returns) ?> posted returns</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Return diagnostic:</strong> <?= pret_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Posted:</strong> <?= pret_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Post Supplier Return</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= pret_h($csrf) ?>"><label>Received Item<select name="receipt_item_id" required><option value="">Choose receipt item…</option><?php foreach($available as $a):?><option value="<?= (int)$a['receipt_item_id'] ?>"><?= pret_h($a['supplier_name'].' • '.$a['invoice_number'].' • '.$a['sku'].' • '.$a['product_name'].' • Returnable '.$a['returnable'].' • Batch '.$a['batch_code']) ?></option><?php endforeach;?></select></label><label>Return Quantity<input type="number" min="0.001" step="0.001" name="quantity" required></label><label>Return Date<input type="date" name="return_date" value="<?= date('Y-m-d') ?>" required></label><label>Actual Supplier Credit Note Amount<input type="number" min="0" step="0.01" name="credit_amount" required><small>Enter the actual supplier credit amount; the system does not infer it from unit cost.</small></label><label>Reason<textarea name="reason" minlength="5" rows="3" required></textarea></label><button>Post Purchase Return →</button></form></article><article class="os-card pp-span-7"><h2>Returnable Received Stock</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Supplier / Invoice</th><th>Product</th><th>Batch</th><th>Received</th><th>Returned</th><th>Returnable</th><th>Batch Stock</th><th>Unit Cost</th></tr></thead><tbody><?php foreach($available as $a):?><tr><td><?= pret_h($a['supplier_name']) ?><small><?= pret_h($a['invoice_number'].' • '.$a['receipt_number']) ?></small></td><td><b><?= pret_h($a['sku']) ?></b><small><?= pret_h($a['product_name']) ?></small></td><td><?= pret_h($a['batch_code']) ?></td><td><?= pret_h($a['quantity_received']) ?></td><td><?= pret_h($a['returned_quantity']) ?></td><td><b><?= pret_h($a['returnable']) ?></b></td><td><?= pret_h($a['batch_stock']) ?></td><td><?= pret_m($a['unit_cost']) ?></td></tr><?php endforeach;?><?php if(!$available):?><tr><td colspan="8">No receipt items currently available for supplier return.</td></tr><?php endif;?></tbody></table></div><h2 style="margin-top:18px">Purchase Return History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Return</th><th>Supplier</th><th>Invoice</th><th>Credit</th><th>Reason</th></tr></thead><tbody><?php foreach($returns as $r):?><tr><td><?= pret_h($r['return_date']) ?></td><td><b><?= pret_h($r['return_number']) ?></b></td><td><?= pret_h($r['supplier_name']) ?></td><td><?= pret_h($r['invoice_number']) ?></td><td><?= pret_m($r['total_credit']) ?></td><td><?= pret_h($r['reason']) ?></td></tr><?php endforeach;?><?php if(!$returns):?><tr><td colspan="6">No purchase returns yet.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>Return rule:</strong> return is batch-specific, cannot exceed the still-returnable receipt quantity, and supplier credit is entered from the real Credit Note rather than inferred.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
